SELECT DISTINCT department, city
FROM employees
ORDER BY department, city;

SELECT COUNT(*) AS rows, COUNT(manager_id) AS with_manager,
       AVG(salary) AS average_salary
FROM employees;

SELECT e.name, d.name AS department
FROM employees e
INNER JOIN departments d ON d.id = e.department_id;

SELECT c.id, o.id AS order_id
FROM customers c
LEFT JOIN orders o ON o.customer_id = c.id AND o.status = 'paid';

SELECT e.name, d.name
FROM employees e
RIGHT JOIN departments d ON e.department_id = d.id;

SELECT COALESCE(a.sku, b.sku) AS sku, a.quantity AS old, b.quantity AS new
FROM old_inventory a
FULL OUTER JOIN new_inventory b ON b.sku = a.sku;

SELECT d.day, s.store_id
FROM calendar_days d
CROSS JOIN stores s;

SELECT e.name AS employee, m.name AS manager
FROM employees e
LEFT JOIN employees m ON e.manager_id = m.id;

SELECT department_id, COUNT(*) AS employees, AVG(salary) AS mean_salary
FROM employees
GROUP BY department_id;

SELECT email FROM customers
UNION ALL
SELECT email FROM prospects;

SELECT revenue / NULLIF(orders, 0) AS average_order_value,
       COALESCE(display_name, username) AS label
FROM customer_metrics;

CREATE TABLE products (
 id bigint PRIMARY KEY,
 sku text UNIQUE NOT NULL,
 price numeric NOT NULL CHECK (price > 0)
);

SELECT id, department_id, salary,
 SUM(salary) OVER (PARTITION BY department_id ORDER BY id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total
FROM employees;

WITH ranked AS (
 SELECT *, ROW_NUMBER() OVER (PARTITION BY department_id ORDER BY salary DESC, id) AS rn FROM employees
) SELECT * FROM ranked WHERE rn <= 3;

SELECT name, salary, DENSE_RANK() OVER (PARTITION BY department_id ORDER BY salary DESC) AS level
FROM employees
WHERE salary IS NOT NULL;

SELECT user_id, happened_at,
 LEAD(happened_at) OVER (PARTITION BY user_id ORDER BY happened_at, id) AS next_event
FROM events;

SELECT day, revenue,
 revenue - LAG(revenue) OVER (ORDER BY day) AS change
FROM daily_sales;

WITH totals AS (
 SELECT customer_id, SUM(amount) AS spent FROM orders GROUP BY customer_id
) SELECT * FROM totals WHERE spent > 1000;

WITH RECURSIVE tree AS (
 SELECT id, manager_id, 0 AS depth FROM employees WHERE manager_id IS NULL
 UNION ALL
 SELECT e.id, e.manager_id, t.depth + 1 FROM employees e JOIN tree t ON e.manager_id = t.id
) SELECT * FROM tree;

